import { Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { LANG_STRINGS } from '../../lang'
import CustomText from '../CustomText'
import PropTypes from 'prop-types'
import { ProviderInfoCardStyle } from './index.style'
import BranchCard from '../../containers/Private/Policy/components/BranchCard'
import isObject from 'lodash/isObject'

function ProviderInfoCard (props) {
  const { logo, providerName, productName, applicationNo, branch, insurLabel = LANG_STRINGS.insuranceNumber } = props

  return (
    <ProviderInfoCardStyle>
      <div className='provider-info-card'>
        <Row>
          <div className='logo-container'>
            <img className='provider-logo' src={logo} alt='logo' />
          </div>
          <div>
            <CustomText
              size='10px'
              color={AgentColorPallette.regular}
              weight={700}
            >
              {providerName}
            </CustomText>
            <CustomText
              size='13px'
              color={AgentColorPallette.regular}
              weight={800}
              bottom='5px'
            >
              {productName}
            </CustomText>
            <CustomText
              size='10px'
              color={AgentColorPallette.regular}
              weight={700}
            >
              {insurLabel}
            </CustomText>
            <CustomText
              size='13px'
              color={AgentColorPallette.uiGold}
              weight={800}
            >
              {applicationNo}
            </CustomText>
          </div>
        </Row>
        {
          branch && isObject(branch) &&
            <BranchCard
              branch={branch}
            />
        }
      </div>
    </ProviderInfoCardStyle>
  )
}

ProviderInfoCard.propTypes = {
  logo: PropTypes.string,
  providerName: PropTypes.string,
  productName: PropTypes.string,
  applicationNo: PropTypes.string,
  insurLabel: PropTypes.string
}

export default ProviderInfoCard
