import { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash/object'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { CustomText, Container } from '../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../lang'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import {
  CustomerPolicyStyle,
  TotalContainerStyle,
  CustomerNoteStyle,
  BtnCustomerPolicyStyle,
  BtnContainerStyle,
} from './index.style'
import { Hr } from '../../../../commonStyle/index.style'
import CustPolicyItems from './components/CustPolicyItems'
import policyActions from '../../../../redux/policy/action'
import { downloadFile } from '../../../../methods/file'
import {
  getVehicleData,
  getCustomerData,
  CUSTOMER_NOTE,
  getOtherCostForVehicle,
  currencyConverter,
  PRODUCT_NAME_MAPPING,
} from '../constants'
import CustomerPremium from './components/CustomerPremium'
import NumberFormat from 'react-number-format'
import { CAR_SVG, DOWNLOAD } from '../../../../images'
import {
  setToLocalStorage,
  clearLocalStorage,
} from '../../../../helpers/localstorage'
import { REDIRECT_URL } from '../../../../constants/cookies'
import { REDIRECT_PAYMENT_STATUS } from '../../../../constants/payment'
import AmountTitle from '../../../../components/AmountTitle'
import {
  FLEET_POLICY,
  MANUAL_ORDER,
  OFFLINE_PACKAGE_CODE,
  RENEW_PURCHASE,
} from '../../../../constants/pkgCode'
import WarningModal from '../../../../components/WarningModal'
import { withRouter } from 'react-router'
import moment from 'moment'
import { getPolicyStatus } from '../../../../helpers/data'
import { size } from 'lodash'
import ProviderInfoCard from '../../../../components/ProviderInfoCard'
import PolicyInfo from '../../../../components/PolicyCancelledRejectionInfo'
class CustomerPolicy extends Component {
  state = {
    showModal: false,
    isOfflinePolicy: false,
    isLoading: false,
  }

  componentDidMount() {
    clearLocalStorage()
    setToLocalStorage(REDIRECT_URL, window.location.pathname)
    if (
      !this.state.isOfflinePolicy &&
      get(this.props, 'customerPolicy.product.package.code', '') ===
        OFFLINE_PACKAGE_CODE
    ) {
      this.setState({
        isOfflinePolicy: true,
      })
    }
  }

  componentDidUpdate(prevProps) {
    const {
      policyPdfStatus,
      policyPdfData,
      policyDraftPdfData,
      policyDraftPdfStatus,
      resetPolicyStore,
      pdfFileDownloadError,
    } = this.props

    if (
      prevProps.policyPdfStatus !== policyPdfStatus ||
      prevProps.policyPdfData !== policyPdfData ||
      prevProps.pdfFileDownloadError !== pdfFileDownloadError ||
      prevProps.resetPolicyStore !== resetPolicyStore
    ) {
      if (policyPdfStatus === 'success' && policyPdfData) {
        this.setState({
          isLoading: false,
        })
        downloadFile(policyPdfData.pdf_url)
        resetPolicyStore(['policyPdfStatus'])
      } else if (policyPdfStatus && pdfFileDownloadError) {
        NotificationManager.error(policyPdfStatus)
        this.setState({
          isLoading: false,
        })
        resetPolicyStore(['policyPdfStatus'])
      }
    }

    if (
      prevProps.policyDraftPdfStatus !== policyDraftPdfStatus ||
      prevProps.policyDraftPdfData !== policyDraftPdfData ||
      prevProps.pdfFileDownloadError !== pdfFileDownloadError ||
      prevProps.resetPolicyStore !== resetPolicyStore
    ) {
      if (policyDraftPdfStatus === 'success' && policyDraftPdfData) {
        downloadFile(policyDraftPdfData.pdf_url)
        resetPolicyStore(['policyDraftPdfStatus'])
        this.setState({
          isLoading: false,
        })
      } else if (policyDraftPdfStatus && pdfFileDownloadError) {
        NotificationManager.error(policyDraftPdfStatus)
        resetPolicyStore(['policyDraftPdfStatus'])
        this.setState({
          isLoading: false,
        })
      }
    }
  }

  handleBuyInsuranceNow = () => {
    // Goto customer Form
    const { customerPolicy = {} } = this.props
    const id =
      this.props.match.params.policyId || this.props.match.params.draftQuoteId
    if (
      [
        'APPLICATION_COMPLETED',
        'PAYMENT_PENDING',
        'PROVISIONAL_CREATED',
        'PARTIAL_INSTALLMENT_PAID',
      ].includes(customerPolicy.status)
    ) {
      this.props.history.push({
        pathname: `/customer/payment/${customerPolicy?.product_key}/${id}`,
        state: {
          customerSummaryData: customerPolicy,
        },
      })
    } else if (customerPolicy.status === 'INITIATED') {
      this.props.history.push({
        pathname: `/customer/policy/${id}/1/summary`,
        state: {
          customerSummaryData: customerPolicy,
        },
      })
    } else if (
      REDIRECT_PAYMENT_STATUS.includes(
        get(customerPolicy, 'payment_status', '')
      )
    ) {
      const transactionId = get(customerPolicy, 'transaction_ids.customer', '')
      this.props.history.push(
        `/customer/payment/success/${transactionId}/${id}`
      )
    } else if (
      ['APPLICATION_CANCELLED', 'PROVISIONAL_FAILED'].includes(
        customerPolicy.status
      )
    ) {
      // if this is the state then show the error on landing page
      return NotificationManager.error(ERROR_LANG.sorryApplicationWasCancelled)
    } else {
      let pathname = ''
      if (customerPolicy.policy_detail?.purchase_type === RENEW_PURCHASE) {
        pathname = `/customer/renewal/policy/form/${id}/1/${customerPolicy.policy_detail?.org_policy_ref_id}`
      } else {
        pathname = this.props.match.params.draftQuoteId
          ? `/customer/draft/policy/${id}/1/form`
          : `/customer/policy/${id}/1/form`
      }
      this.props.history.push({
        pathname,
        state: {
          customerPolicyData: this.props.customerPolicy,
        },
      })
    }
  }

  handleDownloadPdf = () => {
    const { match, getDownloadPdfRequest, getDownloadDraftPdfRequest } =
      this.props
    const draftId = this.props.match.params.draftQuoteId
    if (draftId) {
      getDownloadDraftPdfRequest(draftId)
    } else {
      const policyId = get(match, 'params.policyId')
      getDownloadPdfRequest(policyId)
    }
    this.setState({
      isLoading: true,
    })
  }

  handleToggleModal = () => {
    this.setState((prevState) => ({
      showModal: !prevState.showModal,
    }))
  }

  getInstalmentPayment = (instalmentDetails = {}) => {
    return (
      instalmentDetails.payable_amount +
      (instalmentDetails.admin_fee || 0) +
      (instalmentDetails.stamp_duty || 0) -
      (instalmentDetails.discount || 0)
    )
  }

  renderOfflinePremium = (policy) => {
    const data = [
      {
        name: LANG_STRINGS.basicPremium,
        amount: get(policy, 'product.basic_premium', ''),
      },
      ...getOtherCostForVehicle(policy),
    ]
    return (
      <>
        <CustomText
          color={AgentColorPallette.darkGold}
          size="16px"
          bottom="10px"
          weight={800}
        >
          2. {LANG_STRINGS.customerPremium}
        </CustomText>
        {data.map((premium) =>
          premium.amount ? (
            <AmountTitle
              key={premium.name}
              title={premium.name}
              amount={premium.amount}
              amountPrefix={premium.amountPrefix}
              amountColor={premium.amountColor}
            />
          ) : null
        )}
      </>
    )
  }

  renderNotes = (title, notes, padding) => {
    if (!size(notes)) return null
    return (
      <CustomerNoteStyle padding={padding}>
        <CustomText
          color={AgentColorPallette.black}
          bottom="4px"
          size="13px"
          weight={800}
        >
          {title}:
        </CustomText>
        {notes &&
          notes.map((note, index) => (
            <>
              <CustomText
                key={`note_${index}`}
                color={AgentColorPallette.black}
                bottom="4px"
                lineHeight={1.5}
              >
                {`${index + 1}. ${note.title || note}`}
              </CustomText>
              {note.description &&
                note.description.map &&
                note.description.map((desc, descIndex) => (
                  <CustomText
                    key={`desc_${descIndex}`}
                    color={AgentColorPallette.black}
                    bottom="4px"
                    lineHeight={1.5}
                    size="10px"
                    className="note-description"
                  >
                    &bull;&nbsp;{desc}
                  </CustomText>
                ))}
            </>
          ))}
      </CustomerNoteStyle>
    )
  }

  render() {
    const { customerPolicy = {} } = this.props
    const { isOfflinePolicy, showModal, isLoading } = this.state
    const {
      policy_detail: policyDetail = {},
      customer_data: customerData = {},
      insurance_details: insuranceDetails = {},
      product = {},
      agent_info: agentInfo = {},
      status,
    } = customerPolicy
    const initialStartDate =
      get(policyDetail, 'start_date', '') ||
      get(policyDetail, 'coverage_period_start', '')
    let startDate = ''
    let endDate = ''
    const period = parseInt(policyDetail.coverage_period) || 1
    if (initialStartDate) {
      startDate = moment(initialStartDate, 'YYYY-MM-DD').format("DD MMM'YY")
      endDate = get(policyDetail, 'start_date', '')
        ? moment(initialStartDate, 'YYYY-MM-DD')
            .add(period, 'year')
            .format("DD MMM'YY")
        : moment(get(policyDetail, 'coverage_period_end', '')).format(
            "DD MMM'YY"
          )
    }
    const isHidePDF = [MANUAL_ORDER, FLEET_POLICY].includes(
      customerPolicy.policy_detail.protection_case
    )
    const hideBuyInsurance = [
      'VERIFICATION_PENDING',
      'VERIFICATION_FAILED',
    ].includes(status)
    const isApplicationCancelled = ['REJECTED', 'CANCELLED'].includes(
      customerPolicy?.policy_status
    )
    return (
      <Container loader={isLoading} hideBottomTabs>
        <CustomerPolicyStyle
          className="bg-white"
          isApplicationCancelled={isApplicationCancelled}
        >
          <PolicyInfo
            remarks={insuranceDetails?.remark_details || {}}
            status={customerPolicy?.policy_status || ''}
          />
          <ProviderInfoCard
            logo={product?.logo_url}
            providerName={product?.provider?.name}
            productName={product?.name}
            applicationNo={customerPolicy?.application_no}
            branch={policyDetail?.provider_branch}
            insurLabel={LANG_STRINGS.offerNo}
          />
          <Hr />
          <CustPolicyItems
            title={`1. ${LANG_STRINGS.policyDetail}`}
            data={[
              {
                title: LANG_STRINGS.policyStatus,
                value: getPolicyStatus(customerPolicy.policy_status).text,
              },
              {
                title: LANG_STRINGS.protectionPeriod,
                value:
                  startDate && endDate
                    ? `${startDate} - ${endDate}`
                    : '12 Bulan',
              },
              {
                title: LANG_STRINGS.product,
                value:
                  PRODUCT_NAME_MAPPING.find(
                    (item) => item.code === get(product, 'product_code', '')
                  )?.name || '',
              },
            ]}
          />
          <Hr />
          <CustPolicyItems
            title={`2. ${LANG_STRINGS.customerData}`}
            data={getCustomerData({
              ...customerData,
              address: customerData.customer_address || policyDetail.address,
              ktp_no: policyDetail.ktp_no,
            })}
          />
          <Hr />
          <CustPolicyItems
            title={`3. ${LANG_STRINGS.agentData}`}
            data={[
              {
                title: LANG_STRINGS.fullName,
                value: get(agentInfo, 'name', ''),
              },
              {
                title: LANG_STRINGS.agentId,
                value: get(agentInfo, 'agent_code', ''),
              },
              {
                title: LANG_STRINGS.phoneNumber,
                value: get(agentInfo, 'phone_no', ''),
              },
            ]}
          />
          <Hr />
          {isOfflinePolicy && this.renderOfflinePremium(customerPolicy)}
          {!isOfflinePolicy && (
            <>
              <CustPolicyItems
                title={`4. ${LANG_STRINGS.vehicleData}`}
                data={getVehicleData(policyDetail)}
              />
              <Hr />
            </>
          )}
          {!isOfflinePolicy && (
            <CustomerPremium
              title={`5. ${LANG_STRINGS.customerPremium}`}
              policy={customerPolicy}
            />
          )}
        </CustomerPolicyStyle>
        <TotalContainerStyle>
          <CustomText size="14px">
            {customerPolicy.use_instalment
              ? `Total Tagihan Cicilan ${customerPolicy?.upcoming_instalment?.serial_number}`
              : `Total Premi Per ${policyDetail.coverage_period ? `${policyDetail.coverage_period} tahun` : '12 Bulan'}`}
          </CustomText>
          <NumberFormat
            // hintText="Masukan Harga"
            thousandSeparator="."
            decimalSeparator=","
            decimalScale={2}
            className="format-input"
            prefix={customerPolicy?.policy_detail?.currency_symbol}
            value={
              customerPolicy.use_instalment
                ? currencyConverter(
                    this.getInstalmentPayment(
                      customerPolicy?.upcoming_instalment
                    ),
                    customerPolicy
                  )
                : currencyConverter(
                    get(customerPolicy, 'total_premium', 0) -
                      get(customerPolicy, 'discount', 0),
                    customerPolicy
                  )
            }
            displayType="text"
          />
        </TotalContainerStyle>
        {!isOfflinePolicy && (
          <>
            {this.renderNotes(
              LANG_STRINGS.deductiblesOwnRisk,
              get(customerPolicy, 'product.common_deductible_content', []),
              '20px 20px 0'
            )}
            <CustomerNoteStyle>
              <CustomText color={AgentColorPallette.black} bottom="4px">
                {LANG_STRINGS.note}:
              </CustomText>
              {CUSTOMER_NOTE.map((note, index) => (
                <CustomText
                  key={`note_${index}`}
                  color={AgentColorPallette.black}
                  bottom="4px"
                  lineHeight={1.5}
                >
                  {`${index + 1}. ${note}`}
                </CustomText>
              ))}
            </CustomerNoteStyle>
          </>
        )}
        {!isApplicationCancelled && (
          <BtnContainerStyle>
            {!isOfflinePolicy && !isHidePDF && (
              <BtnCustomerPolicyStyle
                justify="space-between"
                align="center"
                onClick={this.handleDownloadPdf}
                flex={hideBuyInsurance ? 1 : 'auto'}
                backgroundColor={AgentColorPallette.pureYellow}
              >
                <CustomText
                  color={AgentColorPallette.black}
                  size="14px"
                  weight={800}
                >
                  {LANG_STRINGS.downloadFile}
                </CustomText>
                <img src={DOWNLOAD} alt="" />
              </BtnCustomerPolicyStyle>
            )}
            {!hideBuyInsurance && (
              <BtnCustomerPolicyStyle
                justify="space-between"
                align="center"
                position={isOfflinePolicy && 'relative'}
                onClick={this.handleBuyInsuranceNow}
                flex={isOfflinePolicy ? 1 : 'auto'}
                backgroundColor={AgentColorPallette.primary}
              >
                <CustomText
                  color={AgentColorPallette.black}
                  size="14px"
                  weight={800}
                >
                  {LANG_STRINGS.buyInsuranceNow}
                </CustomText>
                <img src={CAR_SVG} alt="" />
              </BtnCustomerPolicyStyle>
            )}
          </BtnContainerStyle>
        )}
        <WarningModal
          showModal={showModal}
          hideCloseBtn
          hideIcon
          warning={LANG_STRINGS.youCanNotPayThisCustomer}
          onClose={this.handleToggleModal}
          onOk={this.handleToggleModal}
        />
        <NotificationContainer />
      </Container>
    )
  }
}

export default withRouter(
  connect(
    (state) => ({
      policyPdfStatus: state.Policy.policyPdfStatus,
      policyPdfData: state.Policy.policyPdfData,
      policyDraftPdfData: state.Policy.policyDraftPdfData,
      policyDraftPdfStatus: state.Policy.policyDraftPdfStatus,
      pdfFileDownloadError: state.Error.GET_DOWNLOAD_PDF,
    }),
    {
      getDownloadPdfRequest: policyActions.getDownloadPdfRequest,
      getDownloadDraftPdfRequest: policyActions.getDraftDownloadPdfReq,
      resetPolicyStore: policyActions.resetPolicyStore,
    }
  )(CustomerPolicy)
)
