import { Component } from 'react'
import PropTypes from 'prop-types'
import { CustPolicyItemStyle } from './index.style'
import VTitleValue from '../VTitlevalue'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'

class CustPolicyItems extends Component {
  static propTypes = {
    data: PropTypes.array,
    title: PropTypes.string
  }

  render () {
    const { title, data = [] } = this.props
    return (
      <>
        <CustomText
          color={AgentColorPallette.darkGold}
          size='16px'
          bottom='10px'
          weight={800}
        >
          {title}
        </CustomText>
        <CustPolicyItemStyle>
          {
            data.map(item => (
              item.value ? (
                <VTitleValue
                  key={item.title}
                  title={item.title}
                  value={item.value}
                  className={`v-title-value ${item.className ? item.className : ''}`}
                />
              ) : null
            ))
          }
        </CustPolicyItemStyle>
      </>
    )
  }
}

export default CustPolicyItems
