import { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { VTitleValueStyle } from './index.style'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'

class VTitleValue extends PureComponent {
  static propTypes = {
    title: PropTypes.string,
    titleSize: PropTypes.string,
    value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    valueColor: PropTypes.string,
    titleAlign: PropTypes.string,
    valueSize: PropTypes.string
  }

  render () {
    const {
      title, titleSize, value, titleAlign,
      valueSize, valueColor, className = ''
    } = this.props
    return (
      <div>
        {
          value &&
            <VTitleValueStyle className={className}>
              <CustomText
                color={AgentColorPallette.fontSemiGrey}
                size={titleSize}
                textAlign={titleAlign}
              >
                {title}
              </CustomText>
              <CustomText
                color={valueColor || AgentColorPallette.black}
                size={valueSize || '14px'}
                weight={800}
              >
                {value}
              </CustomText>
            </VTitleValueStyle>
        }
      </div>
    )
  }
}

export default VTitleValue
