import { Component } from 'react'
import PropTypes from 'prop-types'
import { CustPremiumStyle } from './index.style'
import { isEmpty as lodashIsEmpty } from 'lodash/lang'
import { get as lodashGet } from 'lodash/object'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import AmountTitle from '../../../../../../components/AmountTitle'
import { getBasicPremiumDetails, getBasicAccessoriesDetails, getAddonsDetails, getOtherCostForVehicle, currencyConverter } from '../../../constants'
import { LANG_STRINGS } from '../../../../../../lang'
import { Row } from '../../../../../../commonStyle/index.style'
import NumberFormat from 'react-number-format'
import { ACCESSORY } from '../../../../../../constants/quoatation'
import { FLEET_POLICY, MANUAL_ORDER } from '../../../../../../constants/pkgCode'

class CustomerPremium extends Component {
  static propTypes = {
    title: PropTypes.string,
    policy: PropTypes.object
  }

  getTotalAmountForData = (data = []) => {
    let totalAmount = 0
    data.forEach(item => {
      if (item.type === 'remove') {
        totalAmount -= item.amount
      } else {
        totalAmount += item.amount
      }
    })
    return totalAmount
  }

  getSectionTitleContainer = (title) => (
    <CustomText
      color={AgentColorPallette.mustard}
      size='14px'
      bottom='10px'
      weight={800}
    >
      {title}
    </CustomText>
  )

  getPremiumContainer = (title, data = [], total = {}, showZeroAmount) => {
    if (!lodashGet(data, 'length', 0)) return null
    return (
      <>
        {
          this.getSectionTitleContainer(title)
        }
        {
          data.map(premium => (
            (premium.amount || showZeroAmount) ? (
              <AmountTitle
                key={premium.name}
                title={premium.name}
                amount={premium.amount}
                amountPrefix={premium.amountPrefix}
                amountColor={premium.amountColor}
              />
            ) : null
          ))
        }
        {
          !lodashIsEmpty(total) && (
            <>
              <hr />
              <AmountTitle
                title={total.name}
                color={AgentColorPallette.black}
                amount={this.getTotalAmountForData(data)}
                className='premium-margin-btm'
              />
            </>
          )
        }
      </>
    )
  }

  amountContainerWithSep = (data = {}, className = '', size) => (
    <Row className={`accessories-container ${className}`} align='center'>
      <div>
        {
          data.accessory_type && (
            <CustomText
              color={AgentColorPallette.black}
              size='10px'
              bottom='0'
            >
              {ACCESSORY[data.accessory_type]}
            </CustomText>
          )
        }
        <CustomText
          color={AgentColorPallette.black}
          size={size || '12px'}
          className='amount-title'
        >
          {data.name}
        </CustomText>
      </div>

      <NumberFormat
        // hintText="Masukan Harga"
        thousandSeparator='.'
        decimalSeparator=','
        decimalScale={2}
        className='format-input amount-format'
        prefix='Rp '
        value={data.amount}
        displayType='text'
      />
    </Row>
  )

  getAccessoriesContainer = () => {
    const { policy } = this.props
    const accessories = getBasicAccessoriesDetails(policy) || []
    if (!lodashGet(accessories, 'length', 0)) return null
    return (
      <div>
        <Row justify='space-between'>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='12px'
          >
            Tipe Aksesoris/Nama Aksesoris
          </CustomText>

          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='12px'
          >
            Harga Aksesoris
          </CustomText>
        </Row>
        {
          accessories.map((accessory, i) => (
            this.amountContainerWithSep(accessory, 'vehicle-price-box', '14px')
          ))
        }
      </div>
    )
  }

  render () {
    const { title, policy } = this.props
    const addonsList = getAddonsDetails(policy)
    const prefix = policy?.policy_detail.currency_symbol
    const isManualOrder = policy.policy_detail.protection_case === MANUAL_ORDER
    const isFleetPolicy = policy.policy_detail.protection_case === FLEET_POLICY
    return (
      <>
        <CustomText
          color={AgentColorPallette.darkGold}
          size='16px'
          bottom='10px'
          weight={800}
        >
          {title}
        </CustomText>
        {
          (isManualOrder || isFleetPolicy) && (
            <>
              <AmountTitle
                title={policy.use_instalment ? `${LANG_STRINGS.basicPremium} Cicilan ${policy?.upcoming_instalment?.serial_number}` : LANG_STRINGS.basicPremium}
                color={AgentColorPallette.black}
                amountPrefix={prefix}
                amount={policy.use_instalment ? currencyConverter(policy?.upcoming_instalment?.payable_amount, policy) : currencyConverter(policy.net_premium, policy)}
                className='premium-margin-btm'
              />
              {
                this.getPremiumContainer(
                  '',
                  getOtherCostForVehicle(policy)
                )
              }
            </>
          )
        }
        {
          !(isManualOrder || isFleetPolicy) && (
            <CustPremiumStyle>
              {

                this.getSectionTitleContainer(
                  `5.1 ${LANG_STRINGS.basicPremium}`
                )
              }
              {
                this.amountContainerWithSep(
                  {
                    name: LANG_STRINGS.vehiclePrice,
                    amount: lodashGet(policy, 'policy_detail.vehicle_sum_insured', 0)
                  },
                  'vehicle-price-box',
                  '14px'
                )
              }
              {
                this.getAccessoriesContainer()
              }
              {
                this.getPremiumContainer(
                  '',
                  getBasicPremiumDetails(policy),
                  {
                    name: LANG_STRINGS.newTotalBasicPremium
                  }
                )
              }
              {
                this.getPremiumContainer(
                  `5.2 ${LANG_STRINGS.supplementalLiability}`,
                  addonsList,
                  {
                    name: LANG_STRINGS.totalAdditionalCoverage,
                    amount: ''
                  },
                  true
                )
              }
              {
                this.getPremiumContainer(
                  `${addonsList.length ? '5.3' : '5.2'} ${LANG_STRINGS.otherCost}`,
                  getOtherCostForVehicle(policy)
                )
              }
            </CustPremiumStyle>
          )
        }
      </>
    )
  }
}

export default CustomerPremium
